const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const BRAND_GOLD = "9C7F34";
const BRAND_DARK = "1A1A1A";
const LIGHT_GOLD_BG = "F9F4E8";
const LIGHT_GRAY = "F5F5F5";
const DIVIDER_COLOR = "9C7F34";

function heading1(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 32, font: "Arial", color: BRAND_DARK })],
    spacing: { before: 360, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: DIVIDER_COLOR, space: 6 } }
  });
}

function heading2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: BRAND_GOLD })],
    spacing: { before: 280, after: 120 }
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: "Arial", color: BRAND_DARK, ...opts })],
    spacing: { before: 80, after: 80 },
    alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: BRAND_DARK })],
    spacing: { before: 60, after: 60 }
  });
}

function spacer(n = 1) {
  return new Paragraph({
    children: [new TextRun({ text: "", size: 22 })],
    spacing: { before: 60 * n, after: 60 * n }
  });
}

function cellBorder(color = "DDDDDD") {
  const b = { style: BorderStyle.SINGLE, size: 1, color };
  return { top: b, bottom: b, left: b, right: b };
}

function twoColTable(col1Label, col1Val, col2Label, col2Val) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: cellBorder(),
            width: { size: 4680, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
            margins: { top: 100, bottom: 100, left: 150, right: 150 },
            children: [
              new Paragraph({ children: [new TextRun({ text: col1Label, bold: true, size: 20, font: "Arial", color: BRAND_GOLD })] }),
              new Paragraph({ children: [new TextRun({ text: col1Val, size: 22, font: "Arial", color: BRAND_DARK })] })
            ]
          }),
          new TableCell({
            borders: cellBorder(),
            width: { size: 4680, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
            margins: { top: 100, bottom: 100, left: 150, right: 150 },
            children: [
              new Paragraph({ children: [new TextRun({ text: col2Label, bold: true, size: 20, font: "Arial", color: BRAND_GOLD })] }),
              new Paragraph({ children: [new TextRun({ text: col2Val, size: 22, font: "Arial", color: BRAND_DARK })] })
            ]
          })
        ]
      })
    ]
  });
}

function coverSection() {
  return [
    new Paragraph({
      children: [new TextRun({ text: "", size: 22 })],
      spacing: { before: 200 }
    }),
    // Gold accent bar - use border on paragraph
    new Paragraph({
      children: [new TextRun({ text: "COLLABORATIVE OPPORTUNITY BRIEF", size: 20, font: "Arial", color: "FFFFFF", bold: true })],
      alignment: AlignmentType.CENTER,
      shading: { fill: BRAND_GOLD, type: ShadingType.CLEAR },
      spacing: { before: 120, after: 120 },
      indent: { left: 0, right: 0 }
    }),
    spacer(1),
    new Paragraph({
      children: [new TextRun({ text: "Prepared for Viktor Michael", size: 28, font: "Arial", bold: true, color: BRAND_DARK })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 160, after: 80 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "A Look at Where We Both Operate and How We Might Lift Each Other", size: 22, font: "Arial", color: BRAND_GOLD, italics: true })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 80, after: 80 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "Prepared by The Luxora Collective  |  theluxoracollective.com", size: 20, font: "Arial", color: "888888" })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 120, after: 200 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "", size: 22 })],
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: DIVIDER_COLOR, space: 1 } },
      spacing: { after: 240 }
    }),
  ];
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 540, hanging: 260 } } }
        }]
      }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1260, bottom: 1080, left: 1260 }
      }
    },
    children: [

      // ---- COVER ----
      ...coverSection(),

      // ---- SECTION 1: What We See in Viktor Michael ----
      heading1("What We See in Viktor Michael"),
      spacer(),
      body("First, a genuine compliment: Viktor Michael is doing something that most brands in the aesthetic space are not. You have identified a real, underserved moment in the client journey, post-injection recovery, and built a clinically credible product line around it. The Hidden Agenda serum, the Ciao For Now mask, the 4-stage injection cycle framework: this is thoughtful, science-backed work that stands apart from typical skincare marketing."),
      spacer(),
      body("What Bethany flagged when she came across your brand was not a problem, it was an opportunity. Your post-injection recovery positioning is genuinely unique. Clients who get injectables are actively searching for solutions like yours, and the medspas performing those treatments are the most direct channel to reach them. That connection, between your products and the medspas doing injection work every single day, is where we see real potential for both of us."),
      spacer(),

      // Snapshot table
      heading2("Viktor Michael At a Glance"),
      spacer(),
      twoColTable(
        "Niche", "Post-injection recovery skincare",
        "Product Line", "Serum, Mask, Duo Bundle, Brush"
      ),
      spacer(),
      twoColTable(
        "Founders", "Nadya Kozlova and Shay Sim, clinical aesthetic professionals",
        "Press Recognition", "Harper's Bazaar, Byrdie, Popsugar, CEW and more"
      ),
      spacer(),
      twoColTable(
        "Clinical Credibility", "Proprietary patent-pending Injection Care Complex, dermatologist-tested",
        "Consumer Proof", "97% of study participants saw visible reduction in swelling, bruising and tenderness"
      ),
      spacer(),

      // ---- SECTION 2: The Medspa Market Opportunity ----
      heading1("The Medspa Market and Why It Matters to You"),
      spacer(),
      body("The aesthetic injection market continues to grow year over year. Botox, filler, and biostimulator treatments are no longer reserved for high-end clientele. They have become routine procedures across demographics, performed in medspas at virtually every price point. What has not kept pace is the aftercare conversation."),
      spacer(),
      body("Here is what we see consistently across medspa clients: providers are excellent at the procedure itself, but the post-treatment experience is largely left to the patient. Clients go home with generic ice pack instructions and a pamphlet. There is rarely a curated recovery product recommendation, and almost never a retail opportunity attached to the visit."),
      spacer(),
      body("This is your opening. Viktor Michael fills a gap that medspas are not actively filling for their clients, which means you are not competing with what they already carry. You are adding to it."),
      spacer(),

      heading2("Where the Opportunity Lives"),
      spacer(),
      bullet("Medspas performing 20 or more injection appointments per week are your highest-value targets. At that volume, even modest retail attachment rates create meaningful, recurring revenue for the practice, and consistent product exposure for your brand."),
      bullet("Injectors are trusted advisors. When a provider recommends a recovery product, clients buy it. That warm endorsement carries far more weight than a digital ad."),
      bullet("Post-injection recovery is a growing search category. Clients are already looking for solutions. A medspa that hands them Viktor Michael products is meeting a need that client already has."),
      bullet("Aesthetic Academy relationships, like the Aesthetic Injector Academy, are ideal distribution channels. Injectors trained through these programs are often opening their own practices or joining teams actively looking to differentiate their client experience."),
      spacer(),

      // ---- PAGE BREAK ----
      new Paragraph({ children: [new PageBreak()] }),

      // ---- SECTION 3: Who We Are ----
      heading1("Who We Are: The Luxora Collective"),
      spacer(),
      body("The Luxora Collective is a growth consultancy built specifically for medspas and aesthetic businesses. We do not offer generic business coaching. We work inside the aesthetic industry, with the operators running it, to build the systems, revenue structures, and client experiences that create sustainable growth."),
      spacer(),
      body("Our founder, Bethany, spent a decade running medspa locations before she shifted into consulting. She knows what a busy front desk looks like, what an undertrained team costs, and what a well-built membership program can do for monthly recurring revenue. That operational background is what makes our work practical rather than theoretical."),
      spacer(),
      body("Our signature program, the 90-Day Growth Engine, takes medspas through a structured process to build out their revenue systems: packages, memberships, retail frameworks, client retention strategies, and referral infrastructure. Everything is designed to be implemented by real teams in real practices, not just recommended on a slide deck."),
      spacer(),

      heading2("Our Core Work Includes"),
      spacer(),
      bullet("Medspa revenue system design: packages, bundles, membership programs and upsell frameworks"),
      bullet("Client retention and lifetime value strategy"),
      bullet("Retail integration and product recommendation systems inside treatment flows"),
      bullet("Team training and accountability structures"),
      bullet("90-day structured growth programs with hands-on implementation support"),
      spacer(),

      // ---- SECTION 4: How We Could Collaborate ----
      heading1("How We Could Work Together"),
      spacer(),
      body("We are not reaching out to pitch you on our services. We are reaching out because we think there is a natural, low-friction way for both of our businesses to benefit each other."),
      spacer(),
      body("We work directly with medspas. You need medspas. Those two things overlap in a way that makes a referral relationship genuinely valuable, not just a courtesy arrangement."),
      spacer(),

      heading2("What a Referral Partnership Could Look Like"),
      spacer(),
      twoColTable(
        "We Refer to You", "When a medspa client we work with is building out their retail or aftercare offerings and needs a post-injection recovery product line, we think of Viktor Michael first.",
        "You Refer to Us", "When you connect with medspas that are struggling to grow, retain clients, or structure their business around injection services, you point them toward The Luxora Collective."
      ),
      spacer(),
      body("Neither party has to stretch outside of what they already do. We are already talking to medspas about retail strategy. You are already in conversations with practices about carrying your products. The referral flows naturally from the work both of us are already doing."),
      spacer(),
      body("There is also a longer-term conversation worth having around co-branded education, especially given the Aesthetic Injector Academy relationship in our network. Injectors who are newly trained and building their practices are actively looking for trusted product and business partners. Viktor Michael and The Luxora Collective showing up together in that space is a compelling combination."),
      spacer(),

      // ---- SECTION 5: Let's Connect ----
      heading1("Let's Have a Quick Conversation"),
      spacer(),
      body("Bethany would love to connect with Nadya directly, even just for 20 to 30 minutes, to explore whether this kind of referral relationship makes sense. No agenda, no pitch. Just two people who work in the same world seeing if there is a natural way to support each other."),
      spacer(),
      body("If that sounds worthwhile, we would love to find a time that works for both of you."),
      spacer(2),

      // Contact block
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: {
                  top: { style: BorderStyle.SINGLE, size: 3, color: BRAND_GOLD },
                  bottom: { style: BorderStyle.SINGLE, size: 3, color: BRAND_GOLD },
                  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
                },
                shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
                margins: { top: 160, bottom: 160, left: 240, right: 240 },
                width: { size: 9360, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: "Bethany", bold: true, size: 24, font: "Arial", color: BRAND_DARK })],
                    spacing: { after: 60 }
                  }),
                  new Paragraph({
                    children: [new TextRun({ text: "Founder, The Luxora Collective", size: 22, font: "Arial", color: BRAND_GOLD })],
                    spacing: { after: 60 }
                  }),
                  new Paragraph({
                    children: [new TextRun({ text: "theluxoracollective.com", size: 22, font: "Arial", color: "666666" })],
                    spacing: { after: 40 }
                  }),
                ]
              })
            ]
          })
        ]
      }),
      spacer(2),
      new Paragraph({
        children: [new TextRun({ text: "The Luxora Collective  |  Growth Strategy for Aesthetic Businesses", size: 18, font: "Arial", color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 120 }
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/Viktor_Michael_Collaboration_Brief.docx', buffer);
  console.log("Done.");
});

