const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const BRAND_GOLD = "9C7F34";
const BRAND_DARK = "1A1A1A";
const LIGHT_GOLD_BG = "F9F4E8";
const DIVIDER_COLOR = "9C7F34";
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const rowBorder = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };

function heading1(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 32, font: "Arial", color: BRAND_DARK })],
    spacing: { before: 360, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: DIVIDER_COLOR, space: 6 } }
  });
}

function heading2(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, font: "Arial", color: BRAND_GOLD })],
    spacing: { before: 280, after: 120 }
  });
}

function body(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, font: "Arial", color: BRAND_DARK })],
    spacing: { before: 80, after: 80 }
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, size: 22, font: "Arial", color: BRAND_DARK })],
    spacing: { before: 60, after: 60 }
  });
}

function spacer(n = 1) {
  return new Paragraph({
    children: [new TextRun({ text: "", size: 22 })],
    spacing: { before: 60 * n, after: 60 * n }
  });
}

function twoColTable(col1Label, col1Val, col2Label, col2Val) {
  const b = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
  const borders = { top: b, bottom: b, left: b, right: b };
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders, width: { size: 4680, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
            margins: { top: 100, bottom: 100, left: 150, right: 150 },
            children: [
              new Paragraph({ children: [new TextRun({ text: col1Label, bold: true, size: 20, font: "Arial", color: BRAND_GOLD })] }),
              new Paragraph({ children: [new TextRun({ text: col1Val, size: 21, font: "Arial", color: BRAND_DARK })] })
            ]
          }),
          new TableCell({
            borders, width: { size: 4680, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
            margins: { top: 100, bottom: 100, left: 150, right: 150 },
            children: [
              new Paragraph({ children: [new TextRun({ text: col2Label, bold: true, size: 20, font: "Arial", color: BRAND_GOLD })] }),
              new Paragraph({ children: [new TextRun({ text: col2Val, size: 21, font: "Arial", color: BRAND_DARK })] })
            ]
          })
        ]
      })
    ]
  });
}

function threeColHeaderCell(text, w) {
  return new TableCell({
    borders: {
      top: { style: BorderStyle.SINGLE, size: 3, color: BRAND_GOLD },
      bottom: { style: BorderStyle.SINGLE, size: 3, color: BRAND_GOLD },
      left: noBorder, right: noBorder
    },
    width: { size: w, type: WidthType.DXA },
    shading: { fill: BRAND_GOLD, type: ShadingType.CLEAR },
    margins: { top: 120, bottom: 120, left: 140, right: 140 },
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: "Arial", color: "FFFFFF" })] })]
  });
}

function threeColRow(label, col1, col2, col3, shaded) {
  const fill = shaded ? LIGHT_GOLD_BG : "FFFFFF";
  function labelCell(text, w) {
    return new TableCell({
      borders: { top: rowBorder, bottom: rowBorder, left: noBorder, right: noBorder },
      width: { size: w, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 110, bottom: 110, left: 140, right: 140 },
      children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 20, font: "Arial", color: BRAND_GOLD })] })]
    });
  }
  function cell(text, w) {
    return new TableCell({
      borders: { top: rowBorder, bottom: rowBorder, left: noBorder, right: noBorder },
      width: { size: w, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 110, bottom: 110, left: 140, right: 140 },
      children: [new Paragraph({ children: [new TextRun({ text, size: 20, font: "Arial", color: BRAND_DARK })] })]
    });
  }
  return new TableRow({
    children: [labelCell(label, 1700), cell(col1, 2553), cell(col2, 2554), cell(col3, 2553)]
  });
}

function outcomeRow(phase, col1, col2, col3, shaded) {
  const fill = shaded ? LIGHT_GOLD_BG : "FFFFFF";
  function cell(text, w, gold) {
    return new TableCell({
      borders: { top: rowBorder, bottom: rowBorder, left: noBorder, right: noBorder },
      width: { size: w, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 100, bottom: 100, left: 140, right: 140 },
      children: [new Paragraph({ children: [new TextRun({ text, bold: gold || false, size: 20, font: "Arial", color: gold ? BRAND_GOLD : BRAND_DARK })] })]
    });
  }
  return new TableRow({
    children: [cell(phase, 1600, true), cell(col1, 2586), cell(col2, 2587), cell(col3, 2587)]
  });
}

function oppRow(icon, channel, why, action, shaded) {
  const fill = shaded ? LIGHT_GOLD_BG : "FFFFFF";
  function cell(texts, w) {
    return new TableCell({
      borders: { top: rowBorder, bottom: rowBorder, left: noBorder, right: noBorder },
      width: { size: w, type: WidthType.DXA },
      shading: { fill, type: ShadingType.CLEAR },
      margins: { top: 120, bottom: 120, left: 140, right: 140 },
      children: texts.map((t, i) => new Paragraph({
        children: [new TextRun({ text: t.text, size: 20, font: "Arial", bold: t.bold || false, color: t.color || BRAND_DARK })],
        spacing: { before: i === 0 ? 0 : 40, after: 40 }
      }))
    });
  }
  return new TableRow({
    children: [
      cell([{ text: icon, bold: true, color: BRAND_GOLD }], 480),
      cell([{ text: channel, bold: true }, { text: why }], 3940),
      cell([{ text: action }], 4440),
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 540, hanging: 260 } } } }]
    }]
  },
  styles: { default: { document: { run: { font: "Arial", size: 22 } } } },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1260, bottom: 1080, left: 1260 }
      }
    },
